import React, { useState, useEffect } from "react";

function AdminFacultyBookings() {
  const [bookings, setBookings] = useState([]);
  
  useEffect(() => {
    fetch("http://localhost:8082/faculty-bookings")
      .then((res) => res.json())
      .then((data) => setBookings(data))
      .catch((err) => console.error("Error fetching bookings:", err));
  }, []);

  const handleApproval = async (bookingId, status) => {
    const assignedQuarter = status === "Approved" ? prompt("Enter Assigned Quarter:") : null;
    const adminComments = prompt("Enter Comments (optional):");

    const response = await fetch("http://localhost:8082/faculty-booking/approve", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ bookingId, status, assignedQuarter, adminComments }),
    });

    const result = await response.json();
    if (result.status === "success") {
      alert(result.message);
      setBookings(bookings.filter((b) => b.id !== bookingId));
    } else {
      alert("Failed to update booking.");
    }
  };

  return (
    <div>
      <h2>Admin Faculty Booking Requests</h2>
      {bookings.length === 0 ? <p>No pending requests</p> : (
        <table border="1">
          <thead>
            <tr>
              <th>Faculty Name</th>
              <th>Department</th>
              <th>Level</th>
              <th>Years in BIT</th>
              <th>Requested Quarter Type</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {bookings.map((b) => (
              <tr key={b.id}>
                <td>{b.faculty_name}</td>
                <td>{b.department}</td>
                <td>{b.level}</td>
                <td>{b.years_in_bit}</td>
                <td>{b.quarter_type}</td>
                <td>
                  <button onClick={() => handleApproval(b.id, "Approved")}>Approve</button>
                  <button onClick={() => handleApproval(b.id, "Rejected")}>Reject</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}

export default AdminFacultyBookings;
